  "lines": [
    {
      "id": "chapter.second_year",
      "tiers": [
        {
          "id": "chapter.second_year:t1",
          "title": "Календарь обулся",
          "phrase": "Ты прошёл 50% главы о двух годах пути, 80 днях тренировок и 52 активных неделях. Календарь надел походные ботинки!",
          "imagePrompt": "A walking desk calendar in chunky hiking boots crosses a bridge made of folded calendar sheets, gripping a rope anchored to a kettlebell. Its blank grid face tilts upward toward a distant paper mountain.",
          "fishMarkup": "[warm]Ты прошёл 50% главы о двух годах пути, 80 днях тренировок и 52 активных неделях. Календарь надел <emphasis>походные ботинки!</emphasis>",
          "audioText": "Ты прошёл 50% главы о двух годах пути, 80 днях тренировок и 52 активных неделях. Календарь надел походные ботинки!"
        },
        {
          "id": "chapter.second_year:t2",
          "title": "Выше настенной должности",
          "phrase": "У тебя 75% главы «Второй год»: три четверти длинного маршрута уже позади. Календарь больше не считает себя настенным жителем.",
          "imagePrompt": "The booted desk calendar climbs a steep spiral staircase of folded pages, hauling a tiny alarm clock on a sled. One boot rests on a high landing, while the last paper switchback curls toward the summit.",
          "fishMarkup": "[confident]У тебя <emphasis>75% главы «Второй год»</emphasis>: три четверти длинного маршрута уже позади. [playful]Календарь больше не считает себя настенным жителем.",
          "audioText": "У тебя 75% главы «Второй год»: три четверти длинного маршрута уже позади. Календарь больше не считает себя настенным жителем."
        },
        {
          "id": "chapter.second_year:t3",
          "title": "Будильник, подай тапочки",
          "phrase": "Ты завершил 100% главы: два года пути, 80 дней тренировок и 52 активные недели. Календарь на вершине, будильник — в должности подставки для ног.",
          "imagePrompt": "The booted desk calendar lounges in a folding chair atop the paper mountain, resting both feet on an enormous sleeping alarm clock. A loose calendar page serves as its sunshade, and the tiny sled is parked beside the chair.",
          "fishMarkup": "[triumphant]Ты завершил 100% главы: два года пути, 80 дней тренировок и 52 активные недели. Календарь на вершине, <slow>будильник —</slow> [playful]в должности подставки для ног.",
          "audioText": "Ты завершил 100% главы: два года пути, 80 дней тренировок и 52 активные недели. Календарь на вершине, будильник — в должности подставки для ног."
        }
      ]
    },
    {
      "id": "chapter.veteran",
      "tiers": [
        {
          "id": "chapter.veteran:t1",
          "title": "Архив на лапах",
          "phrase": "Ты собрал 50% главы на пути к 120 дням тренировок, 1000 подходам и 52 активным неделям. Архив твоей истории уже просит отдельную полку.",
          "imagePrompt": "A sturdy tortoise carries a small wooden shelf across its shell, with plain-spined training journals tucked between dumbbell bookends. It carefully slides one more journal into place with a front foot.",
          "fishMarkup": "[warm]Ты собрал 50% главы на пути к 120 дням тренировок, 1000 подходам и 52 активным неделям. Архив твоей истории уже просит <emphasis>отдельную полку.</emphasis>",
          "audioText": "Ты собрал 50% главы на пути к 120 дням тренировок, 1000 подходам и 52 активным неделям. Архив твоей истории уже просит отдельную полку."
        },
        {
          "id": "chapter.veteran:t2",
          "title": "Тихо, подходы записываются",
          "phrase": "В главе «Ветеран» у тебя уже 75% пути к 120 дням тренировок, 1000 подходам и 52 активным неделям. Железо в твоём архиве само переходит на шёпот.",
          "imagePrompt": "The tortoise now carries a two-tier library shelf fitted neatly around its shell. Two tiny walking dumbbells push a cart of plain-spined journals up a short ramp, while the tortoise raises one foot in a gentle shushing gesture.",
          "fishMarkup": "[confident]В главе «Ветеран» у тебя уже <emphasis>75% пути</emphasis> к 120 дням тренировок, 1000 подходам и 52 активным неделям. [playful]Железо в твоём архиве само переходит на шёпот.",
          "audioText": "В главе «Ветеран» у тебя уже 75% пути к 120 дням тренировок, 1000 подходам и 52 активным неделям. Железо в твоём архиве само переходит на шёпот."
        },
        {
          "id": "chapter.veteran:t3",
          "title": "Железо в читальном зале",
          "phrase": "За твоими 100% главы «Ветеран» — 120 дней тренировок, 1000 подходов и 52 активные недели. Железо пришло за опытом — и получило читательский билет.",
          "imagePrompt": "The tortoise's shell has become a grand mobile library packed with plain-spined training journals. It sits at a checkout desk built into the shell, handing a tiny library card to a barbell as dumbbells queue with books.",
          "fishMarkup": "[triumphant]За твоими 100% главы «Ветеран» — 120 дней тренировок, 1000 подходов и 52 активные недели. Железо пришло за опытом <slow>— и получило</slow> [playful]читательский билет.",
          "audioText": "За твоими 100% главы «Ветеран» — 120 дней тренировок, 1000 подходов и 52 активные недели. Железо пришло за опытом — и получило читательский билет."
        }
      ]
    }
  ]
}
